// Generated by Suite Builder from a crawl of the site. Traceability: each criterion, its test, where it is, how it last ran.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira-loop/jira.properties (jira login fills them in).
// Traceability (step 6): each criterion of a story, the test that checks it (the story id the test
// carries), where that test is, linked at this commit when the repository is on GitHub or GitLab and holds
// it, and how it last ran. Read by sync.mjs: the done comment's table (report) and each card's results
// comment, edited in place (results). Reads the suite's files and git; starts nothing else.
import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { basename, dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (file) => readFileSync(file, 'utf8');
const posix = (path) => path.split(sep).join('/');
const walk = (dir, keep) =>
  !existsSync(dir)
    ? []
    : readdirSync(dir).flatMap((name) => {
        const path = join(dir, name);
        return statSync(path).isDirectory() ? walk(path, keep) : keep(name) ? [path] : [];
      });
const escape = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Where the tests are, how a file is one, and how a test says its story: @Story("KEY-1"). */
const TESTS = join(ROOT, 'src', 'test');
const isTest = (name) => name.endsWith('.java');
const MARKER = '@Story\\(\\s*(?:value\\s*=\\s*)?';

/** A criterion's test: its class and the method under the line that names its story. */
function named(lines, i, file) {
  const method = lines
    .slice(i, i + 8)
    .map((l) => /\bvoid\s+(\w+)\s*\(/.exec(l)?.[1])
    .find(Boolean);
  return `${basename(file).replace(/\.\w+$/, '')}${method ? `.${method}` : ''}`;
}

/** The last run's results by Class.method, from the Surefire reports; null when nothing has run. */
function runResults() {
  const files = walk(join(ROOT, 'target', 'surefire-reports'), (n) => /^TEST-.*\.xml$/.test(n));
  if (!files.length) return null;
  const states = new Map();
  for (const file of files) {
    for (const m of read(file).matchAll(/<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g)) {
      const name = /\bname="([^"(]*)/.exec(m[1])?.[1];
      const cls = /\bclassname="([^"]*)"/.exec(m[1])?.[1]?.split('.').pop();
      const inner = m[3] ?? '';
      const state = /<(failure|error)\b/.test(inner) ? 'failed' : /<skipped\b/.test(inner) ? 'skipped' : 'passed';
      if (name && cls) states.set(`${cls}.${name}`, state);
    }
  }
  return (test) => states.get(test.name) ?? null;
}

/** Each criterion of the story (its id and the criterion's own, KEY-n), by id: its test's name, file and line. */
export function criteria(key) {
  const out = new Map();
  const marked = new RegExp(`${MARKER}["'\`](${escape(key)}(?:-\\d+)?)["'\`]`, 'i');
  for (const file of walk(TESTS, isTest)) {
    const lines = read(file).split(/\r?\n/);
    lines.forEach((line, i) => {
      const m = marked.exec(line);
      if (m)
        out.set(m[1].toUpperCase(), { name: named(lines, i, file), file: posix(relative(ROOT, file)), line: i + 1 });
    });
  }
  return new Map([...out].sort(([a], [b]) => a.localeCompare(b, undefined, { numeric: true })));
}

const git = (...args) => {
  const run = spawnSync('git', args, { cwd: ROOT, encoding: 'utf8' });
  return run.status === 0 ? run.stdout.trim() : '';
};

/** A link to a file's line at this commit, or null: the repository on GitHub or GitLab, and the commit pushed. */
export function linker() {
  const remote = git('remote', 'get-url', 'origin')
    .replace(/^git@([^:]+):/, 'https://$1/')
    .replace(/\.git$/, '')
    .replace(/^https:\/\/[^@/]+@/, 'https://');
  const sha = git('rev-parse', 'HEAD');
  const pushed = sha && git('branch', '-r', '--contains', sha);
  if (!remote.startsWith('https://') || !pushed) return () => null;
  const blob = /gitlab/.test(remote) ? '/-/blob/' : /github/.test(remote) ? '/blob/' : null;
  return blob ? (file, line) => `${remote}${blob}${sha}/${file}#L${line}` : () => null;
}

/** The criteria as a Jira table: each with its test, where it is (linked), and, given, how it last ran; then those waiting. */
export function table(key, waiting = [], ran = null) {
  const found = criteria(key);
  const link = linker();
  const cell = (text) =>
    String(text)
      .replace(/[|[\]{}]/g, ' ')
      .trim() || ' ';
  const rows = [...found].map(([id, t]) => {
    const at = `${basename(t.file)}:${t.line}`;
    const url = link(t.file, t.line);
    return `|${id}|${cell(t.name)}|${url ? `[${at}|${url}]` : cell(at)}|${ran ? `${cell(ran(t, id) ?? 'not run')}|` : ''}`;
  });
  const head = `||Criterion||Test||Where||${ran ? 'Last run||' : ''}`;
  const open = waiting.map((w) => `|${cell(w)}|waiting on the story's person| |${ran ? ' |' : ''}`);
  return rows.length + open.length ? [head, ...rows, ...open].join('\n') : '';
}

/** How each test last ran, by the name criteria() gives it, from the last run's report; null when nothing has run. */
export function lastRun() {
  return runResults();
}
